DO $$ DECLARE r record; n int := 0; BEGIN FOR r IN SELECT id FROM public.crm_runsheets WHERE emailed_at IS NOT NULL OR cardinality(emailed_to)>0 LOOP BEGIN PERFORM public.crm_sync_runsheet_roster(r.id); n := n + 1; EXCEPTION WHEN others THEN RAISE WARNING 'runsheet % not projected: %', r.id, SQLERRM; END; END LOOP; RAISE NOTICE 'projected % emailed run sheets into roster', n; END $$;